import json
import os
import urllib.parse
import urllib.request

# Allow deployments to select the live service endpoint after service migrations.
BASE = os.environ.get("PRICES_BASE_URL", "http://prices.internal/api/v1/price")


def get_price(sku: str) -> float:
    url = f"{BASE.rstrip('/')}/{urllib.parse.quote(sku, safe='')}"
    with urllib.request.urlopen(url, timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    return sum((get_price(s) for s in skus), 0.0)
